"""Structured profile translation of ADR 0035: the English identity slots and wardrobe tags of a card, generated by
the text model as VisualIdentityResult under a grammar built from the tag vocabulary, then merged without touching
what the card locks.

Delivered here: the generation, its validation and the merge. Not delivered yet: the `visual_profile_translate` job
handler that runs this under an llm lease, the save path that queues it when a description changes, and the write of
the merged slots (docs/image-generation.md, Visual consistency).
"""

from collections.abc import Mapping
from dataclasses import dataclass
from types import MappingProxyType
from typing import Any

from pydantic import ValidationError

from lyrveil.catalog import TextTemplate
from lyrveil.domain.card import CharacterCard, LockableField, VisualProfile
from lyrveil.domain.errors import ContentPolicyBlockedError, ValidationFailedError
from lyrveil.images.tags import TagVocabulary, load_vocabulary
from lyrveil.ports.text_runtime import TextRuntime
from lyrveil.prompts import visual_profile
from lyrveil.prompts.structured import OutputRejectedError, generate_structured
from lyrveil.prompts.visual_profile import VisualIdentityResult, identity_grammar
from lyrveil.services.card_rules import describe_error, validate_card

# ADR 0035 (Locks): the slots each locked visual field protects. `extra` and the named outfits have no lock.
LOCKED_SLOTS: Mapping[LockableField, tuple[str, ...]] = MappingProxyType(
    {
        "hair": ("hair_color", "hair_length", "hairstyle"),
        "eyes": ("eye_color",),
        "face": ("face", "skin"),
        "body": ("body",),
        "distinctive_marks": ("marks",),
        "accessories": ("accessories",),
        "art_style": ("style",),
        "clothing": ("usual_outfit_en",),
    }
)
_IDENTITY_SLOTS = (*visual_profile.SINGLE_SLOTS, *visual_profile.LIST_SLOTS, "extra")
_REPEATED_OUTFIT = "La risposta elenca due volte lo stesso abito."
_UNKNOWN_OUTFIT = "La risposta nomina un abito che la scheda non ha."


@dataclass(frozen=True)
class TranslatedCard:
    """The card with its translated slots, the model's result as validated, and the generations it took (1, or 2
    after a repair)."""

    card: CharacterCard
    result: VisualIdentityResult
    attempts: int


def locked_slots(visual: VisualProfile) -> frozenset[str]:
    """Returns the slots of `visual` that a translation must not rewrite, by its locked fields."""
    return frozenset(slot for field in visual.locked_fields for slot in LOCKED_SLOTS[field])


def apply_identity_result(visual: VisualProfile, result: VisualIdentityResult) -> VisualProfile:
    """Returns `visual` with the slots and wardrobe tags of `result`, except the locked slots, which keep their value.

    A named outfit takes the tags listed under its key; an outfit the result leaves out keeps its tags. Raises
    OutputRejectedError when the result lists a key twice or a key the card does not have. The Italian fields, the
    locks and every other field are unchanged. Vocabulary membership is not checked here: validate_card does it.
    """
    locked = locked_slots(visual)
    slots: dict[str, Any] = {slot: getattr(result, slot) for slot in _IDENTITY_SLOTS if slot not in locked}
    keys = [outfit.key for outfit in result.outfits]
    if len(set(keys)) != len(keys):
        raise OutputRejectedError(_REPEATED_OUTFIT)
    tags_by_key = {outfit.key: outfit.tags_en for outfit in result.outfits}
    if set(tags_by_key) - {outfit.key for outfit in visual.outfits}:
        raise OutputRejectedError(_UNKNOWN_OUTFIT)
    outfits = [
        outfit.model_copy(update={"tags_en": tags_by_key[outfit.key]}) if outfit.key in tags_by_key else outfit
        for outfit in visual.outfits
    ]
    changes: dict[str, Any] = {"identity_en": visual.identity_en.model_copy(update=slots), "outfits": outfits}
    if "usual_outfit_en" not in locked:
        changes["usual_outfit_en"] = result.usual_outfit_en
    return visual.model_copy(update=changes)


async def translate_visual_profile(
    runtime: TextRuntime,
    card: CharacterCard,
    *,
    template: TextTemplate,
    genkey: str,
    vocabulary: TagVocabulary | None = None,
) -> TranslatedCard:
    """Generates the English slots of `card` and returns the card with them merged by apply_identity_result.

    The model writes under identity_grammar, so its slots can only hold vocabulary tags and its outfits only the
    card's keys. The output is still validated: by VisualIdentityResult, by the merge, and by validate_card on the
    whole merged card, which sanitizes the tags, refuses a slot outside the vocabulary or a free tag over 4 words,
    and runs the content guard. A refusal gets the one repair of generate_structured, with an Italian reason that
    names fields and never values. Requires the caller's llm lease. Raises StructuredOutputInvalidError when the
    output and its repair are both refused, and lets a TextRuntimeError through for the scheduler to retry. The
    model's text and the card are never logged.
    """
    words = vocabulary or load_vocabulary()
    grammar = identity_grammar(words, [outfit.key for outfit in card.visual.outfits])

    def validate(raw: dict[str, Any]) -> tuple[CharacterCard, VisualIdentityResult]:
        try:
            result = VisualIdentityResult.model_validate(raw)
        except ValidationError as error:
            raise OutputRejectedError(describe_error(error)) from None
        merged = card.model_copy(update={"visual": apply_identity_result(card.visual, result)})
        try:
            return validate_card(merged.model_dump(mode="json")), result
        except (ValidationFailedError, ContentPolicyBlockedError) as error:
            raise OutputRejectedError(error.detail) from None

    generated = await generate_structured(
        runtime,
        prompt=lambda repair: visual_profile.render_prompt(template, card.visual, words, repair),
        grammar=grammar,
        validate=validate,
        genkey=genkey,
        max_length=visual_profile.MAX_LENGTH,
        temperature=visual_profile.TEMPERATURE,
    )
    translated, result = generated.value
    return TranslatedCard(card=translated, result=result, attempts=generated.attempts)
